<template><LearnecAppShell role="ADMIN"><section data-admin-data class="data"><header><div><p>教学闭环 / 数据中心</p><h1>班级学情分析</h1></div><select v-model="classId" @change="load"><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.name }}</option></select></header><div v-if="data" class="metrics"><article><span>批阅完成率</span><strong>{{ data.overview.completionPercent }}%</strong></article><article><span>已批阅工单</span><strong>{{ data.overview.gradedCount }}</strong></article><article><span>平均总分</span><strong>{{ data.overview.averageScore }}</strong></article><article><span>区块自动得分率</span><strong>{{ data.sectionScoreRate }}%</strong></article></div><section v-if="data"><div class="heading"><h2>成绩排行</h2><button @click="download">导出 .xlsx</button></div><table><thead><tr><th>学号</th><th>姓名</th><th>已批阅</th><th>平均分</th></tr></thead><tbody><tr v-for="row in data.rankings" :key="row.studentId"><td>{{ row.studentNumber }}</td><td>{{ row.studentName }}</td><td>{{ row.gradedCount }}</td><td>{{ row.averageScore }}</td></tr></tbody></table></section></section></LearnecAppShell></template>
<script setup lang="ts">const ssrHeaders=import.meta.server?useRequestHeaders(['cookie']):undefined;const classes=ref<any[]>([]);const classId=ref('');const data=ref<any>(null);async function load(){if(classId.value)data.value=await $fetch(`/api/admin/data?classId=${classId.value}`,{headers:ssrHeaders})}async function download(){const blob=await $fetch<Blob>(`/api/admin/data/export?classId=${classId.value}`,{responseType:'blob'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='班级成绩单.xlsx';link.click();URL.revokeObjectURL(link.href)}const response=await useFetch<{classes:any[]}>('/api/admin/classes',{headers:ssrHeaders});classes.value=response.data.value?.classes??[];classId.value=classes.value[0]?.id??'';await load()</script>
<style scoped>.data header,.heading{display:flex;justify-content:space-between;align-items:end;gap:16px}.data p{margin:0;color:#1677ff;font-size:13px;font-weight:700}.data h1{margin:7px 0 22px;font-size:28px}.data select,.data button{border:1px solid #d0d5dd;border-radius:5px;padding:9px;background:#fff}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px}.metrics article,table{border:1px solid #e4e8ef;background:#fff}.metrics article{padding:18px}.metrics span{display:block;color:#667085;font-size:13px}.metrics strong{display:block;margin-top:10px;font-size:26px}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{padding:12px;border-bottom:1px solid #eef1f5;text-align:left}@media(max-width:700px){.data header,.heading{align-items:flex-start;flex-direction:column}.metrics{grid-template-columns:repeat(2,1fr);}.data{overflow:hidden}table{font-size:13px}}</style>
